<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';

use TripleR\Config;
use TripleR\Database;
use TripleR\Services\RentalRuntimeFactory;

if(!function_exists('curl_init')){fwrite(STDERR,"PHP curl extension is required for M7 HTTP acceptance.\n");exit(2);}
$base=rtrim(Config::require('M4_HTTP_BASE_URL'),'/');$password=Config::require('M4_HTTP_TEST_PASSWORD');$db=Database::connection();$tag=bin2hex(random_bytes(5));$failures=0;
function m7check(bool $ok,string $label,string $detail=''):void{global $failures;if($ok){echo "PASS: $label\n";return;}$failures++;echo "FAIL: $label".($detail===''?'':" ($detail)")."\n";}
function m7reject(callable $fn,string $needle,string $label):void{try{$fn();m7check(false,$label,'statement was accepted');}catch(\PDOException $e){m7check(str_contains(strtolower($e->getMessage()),strtolower($needle)),$label,$e->getMessage());}}
function m7request($client,string $method,string $path,?array $form=null):array{$headers=[];curl_setopt_array($client,[CURLOPT_URL=>$GLOBALS['base'].$path,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>false,CURLOPT_HEADERFUNCTION=>static function($ch,string $line)use(&$headers):int{$n=strlen($line);if(str_contains($line,':')){[$k,$v]=explode(':',$line,2);$headers[strtolower(trim($k))]=trim($v);}return $n;},CURLOPT_FOLLOWLOCATION=>false]);if($method==='POST')curl_setopt_array($client,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($form??[])]);else curl_setopt($client,CURLOPT_HTTPGET,true);$body=curl_exec($client);if(!is_string($body))throw new RuntimeException('M7 HTTP request failed: '.curl_error($client));return ['status'=>(int)curl_getinfo($client,CURLINFO_RESPONSE_CODE),'body'=>$body,'headers'=>$headers];}
function m7multipart($client,string $path,array $form,string $filePath):array{$headers=[];$form['photos[0]']=new CURLFile($filePath,'image/png','inspection.png');curl_setopt_array($client,[CURLOPT_URL=>$GLOBALS['base'].$path,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$form,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>false,CURLOPT_HEADERFUNCTION=>static function($ch,string $line)use(&$headers):int{$n=strlen($line);if(str_contains($line,':')){[$k,$v]=explode(':',$line,2);$headers[strtolower(trim($k))]=trim($v);}return $n;},CURLOPT_FOLLOWLOCATION=>false]);$body=curl_exec($client);if(!is_string($body))throw new RuntimeException('M7 multipart request failed: '.curl_error($client));return ['status'=>(int)curl_getinfo($client,CURLINFO_RESPONSE_CODE),'body'=>$body,'headers'=>$headers];}
function m7login(array $account):array{$client=curl_init();curl_setopt_array($client,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>'',CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>10]);$login=m7request($client,'GET','/staff/login');if(!preg_match('/name="_csrf"\s+value="([^"]+)"/',$login['body'],$m))throw new RuntimeException('M7 login CSRF token missing.');$res=m7request($client,'POST','/staff/login',['_csrf'=>html_entity_decode($m[1],ENT_QUOTES|ENT_HTML5,'UTF-8'),'email'=>$account['email'],'password'=>$GLOBALS['password']]);if($res['status']!==303&&$res['status']!==200)throw new RuntimeException('M7 HTTP login failed: '.$account['role']);$page=m7request($client,'GET','/staff');if(!preg_match('/name="_csrf"\s+value="([^"]+)"/',$page['body'],$m))throw new RuntimeException('M7 authenticated CSRF token missing.');return [$client,html_entity_decode($m[1],ENT_QUOTES|ENT_HTML5,'UTF-8')];}
function m7fixture(string $suffix,string $date):int{global $db;$tag=bin2hex(random_bytes(4));$q=$db->prepare("INSERT INTO vehicles(plate_number,make,model,model_year,color,body_type,transmission,fuel_type,seating_capacity,daily_rate,current_status) VALUES(?, 'Test','Damage',2024,'White','sedan','automatic','gasoline',5,1000,'available')");$q->execute(['M7H-'.$tag]);$vehicle=(int)$db->lastInsertId();$q=$db->prepare("INSERT INTO customers(full_name,customer_type) VALUES(?, 'walk_in')");$q->execute(['M7 HTTP '.$suffix.' '.$tag]);$customer=(int)$db->lastInsertId();$service=RentalRuntimeFactory::service($db);$id=$service->create(['customer_id'=>$customer,'vehicle_id'=>$vehicle,'rental_type'=>'self_drive','start_date'=>$date,'end_date'=>$date,'scheduled_pickup_at'=>$date.'T10:00','scheduled_return_at'=>$date.'T18:00','deposit_amount'=>'0'],1);$service->recordDownpayment($id,'T'.strtoupper(bin2hex(random_bytes(8))),1);$service->transition($id,'confirm',1);return $id;}

$accounts=[];foreach(['front_desk','fleet_manager','finance_staff','auditor','support_staff','system_admin'] as $role){$email="m7-$role-$tag@example.test";$q=$db->prepare('INSERT INTO users(email,password_hash,role,is_active,must_change_password) VALUES(:email,:hash,:role,1,0)');$q->execute(['email'=>$email,'hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role]);$accounts[$role]=['email'=>$email,'role'=>$role];}
$today=(new DateTimeImmutable('today',new DateTimeZone('Asia/Manila')))->format('Y-m-d');$agreement=m7fixture('pre',$today);
[$front,$frontCsrf]=m7login($accounts['front_desk']);$frontPost=m7request($front,'POST','/rentals/damage/report',['_csrf'=>$frontCsrf,'agreement_id'=>$agreement,'phase'=>'pre','has_damage'=>'1','location'=>'left door','damage_type'=>'dent','severity'=>'minor','repair_cost_suggestion'=>'1500.00']);m7check($frontPost['status']===303,'front_desk can capture damage reports');
$q=$db->prepare('SELECT report_id FROM damage_reports WHERE agreement_id=:id AND has_damage=1');$q->execute(['id'=>$agreement]);$report=(int)$q->fetchColumn();
$frontDecision=m7request($front,'POST','/rentals/damage/liability',['_csrf'=>$frontCsrf,'agreement_id'=>$agreement,'report_id'=>$report,'customer_liable'=>'1','liable_amount'=>'1500.00','reason'=>'Front desk must not decide liability']);m7check($frontDecision['status']===403,'front_desk cannot determine liability');
[$manager,$managerCsrf]=m7login($accounts['fleet_manager']);$decisionResponse=m7request($manager,'POST','/rentals/damage/liability',['_csrf'=>$managerCsrf,'agreement_id'=>$agreement,'report_id'=>$report,'customer_liable'=>'1','liable_amount'=>'1500.00','reason'=>'Manager determination']);m7check($decisionResponse['status']===303,'fleet_manager can determine liability');
$q=$db->prepare('SELECT decision_id FROM damage_liability_decisions WHERE report_id=:id');$q->execute(['id'=>$report]);$decision=(int)$q->fetchColumn();
[$auditor,$auditorCsrf]=m7login($accounts['auditor']);$agreementPage=m7request($auditor,'GET','/rentals/detail?agreement_id='.$agreement);m7check($agreementPage['status']===200&&str_contains($agreementPage['body'],'Damage inspections'),'agreement detail displays M7 inspections');$reportDetail=m7request($auditor,'GET','/rentals/damage/detail?report_id='.$report);m7check($reportDetail['status']===200&&str_contains($reportDetail['body'],'Liability decision history'),'auditor can read the dedicated damage report detail');$auditorReport=m7request($auditor,'POST','/rentals/damage/report',['_csrf'=>$auditorCsrf,'agreement_id'=>$agreement,'phase'=>'during','has_damage'=>'0']);m7check($auditorReport['status']===403,'auditor cannot capture or mutate reports');
$auditorLiability=m7request($auditor,'POST','/rentals/damage/liability',['_csrf'=>$auditorCsrf,'agreement_id'=>$agreement,'report_id'=>$report,'customer_liable'=>'1','liable_amount'=>'1500.00','reason'=>'Denied']);m7check($auditorLiability['status']===403,'auditor cannot determine liability');
$auditorCharge=m7request($auditor,'POST','/rentals/damage/charge',['_csrf'=>$auditorCsrf,'agreement_id'=>$agreement,'decision_id'=>$decision,'amount'=>'1500.00']);m7check($auditorCharge['status']===403,'auditor cannot post a charge');
[$finance,$financeCsrf]=m7login($accounts['finance_staff']);$charge=m7request($finance,'POST','/rentals/damage/charge',['_csrf'=>$financeCsrf,'agreement_id'=>$agreement,'decision_id'=>$decision,'amount'=>'1400.00','adjustment_reason'=>'Shop discount']);m7check($charge['status']===303,'finance_staff can post an adjusted damage charge');
$q=$db->prepare('SELECT COUNT(*) FROM rental_charges WHERE damage_decision_id=:id AND damage_adjustment_reason=\'Shop discount\' AND amount=1400.00');$q->execute(['id'=>$decision]);m7check((int)$q->fetchColumn()===1,'finance adjustment reason is recorded');

$active=m7fixture('during',$today);$runtime=RentalRuntimeFactory::service($db);$runtime->transition($active,'pickup',1,null,9000);$png=tempnam(sys_get_temp_dir(),'m7png');$pngBytes=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j2ioAAAAASUVORK5CYII=',true);file_put_contents($png,$pngBytes);
$upload=m7multipart($front,'/rentals/damage/report',['_csrf'=>$frontCsrf,'agreement_id'=>$active,'phase'=>'during','has_damage'=>'1','location'=>'hood','damage_type'=>'scratch','severity'=>'minor','repair_cost_suggestion'=>'200.00'],$png);m7check($upload['status']===303,'during damage accepts a validated uploaded photo');
$q=$db->prepare('SELECT photo_id,storage_path FROM photos p JOIN damage_reports r ON r.report_id=p.damage_report_id WHERE r.agreement_id=:id');$q->execute(['id'=>$active]);$photo=$q->fetch();m7check((bool)$photo&&str_starts_with((string)$photo['storage_path'],'damage/'),'damage photo is stored under private damage storage');
$migrationDb=Database::migrationConnection();m7reject(fn()=>$migrationDb->exec('UPDATE photos SET original_filename=\'changed.png\' WHERE photo_id='.(int)$photo['photo_id']),'append-only','damage photos reject direct UPDATE');m7reject(fn()=>$migrationDb->exec('DELETE FROM photos WHERE photo_id='.(int)$photo['photo_id']),'append-only','damage photos reject direct DELETE');
$guest=curl_init();curl_setopt_array($guest,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>'',CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>10]);$guestPhoto=m7request($guest,'GET','/rentals/damage/photo?photo_id='.(int)$photo['photo_id']);m7check($guestPhoto['status']===303,'unauthenticated photo retrieval is rejected');
$auditorPhoto=m7request($auditor,'GET','/rentals/damage/photo?photo_id='.(int)$photo['photo_id']);m7check($auditorPhoto['status']===200&&($auditorPhoto['headers']['content-type']??'')==='image/png'&&$auditorPhoto['body']===$pngBytes,'auditor can read authenticated private evidence');m7check(($auditorPhoto['headers']['cache-control']??'')==='private, no-store','damage photo response is private and non-cacheable');

foreach([$front,$manager,$auditor,$finance,$guest] as $c)curl_close($c);@unlink($png);
if($failures>0){fwrite(STDERR,"M7 HTTP checks failed: $failures\n");exit(1);}echo "All M7 HTTP role and evidence checks passed.\n";
